/* Customizable synthetic resource registry. No network, repository checkout or Skill execution. */
(() => {
  'use strict';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const input=(label,key,value)=>`<label class="admin-field">${label}<input data-field="${key}" value="${esc(value)}"></label>`;
  const select=(label,key,value,items)=>`<label class="admin-field">${label}<select data-field="${key}">${items.map(([id,name])=>`<option value="${id}" ${id===value?'selected':''}>${name}</option>`).join('')}</select></label>`;
  const toggle=(label,key,value)=>`<label class="admin-toggle"><span>${label}</span><input type="checkbox" data-field="${key}" ${value?'checked':''}></label>`;
  const checks=(title,key,items,selected)=>`<h3>${title}</h3>${items.map(x=>`<label class="admin-check"><input type="checkbox" data-grant="${key}" value="${x.id}" ${(selected||[]).includes(x.id)?'checked':''}>${esc(x.name)}${x.enabled?'':' · 已停用'}</label>`).join('')||'<p class="admin-muted">目录为空，请先新增。</p>'}`;
  const modes=[['confirm','本人确认（有权时）'],['auto_readonly','允许范围内自动只读检查'],['approval','每次交负责人审批'],['collect_only','仅收集问题，不执行']];
  const initial={
    projects:['orders','payments','reports'].map(id=>({...window.CodeSource.defaults,id:'demo-'+id+'-code',name:{orders:'订单项目',payments:'支付项目',reports:'报表项目'}[id],address:'https://git.example.invalid/team/'+id+'.git',defaultRef:'demo-commit-a',paths:'src/, docs/',credentialRef:'secret-ref/demo-repo-readonly',enabled:true,revision:1})),
    mcps:[{id:'demo-data-mcp',name:'报表只读 MCP',transport:'http',address:'https://tools.example.invalid/report/mcp',credentialRef:'secret-ref/demo-mcp',readOnly:true,tools:'report.read, detail.read',enabled:true,revision:1},{id:'demo-log-mcp',name:'日志只读 MCP',transport:'http',address:'https://tools.example.invalid/log/mcp',credentialRef:'secret-ref/demo-mcp',readOnly:true,tools:'logs.search',enabled:true,revision:1}],
    skills:[{id:'demo-report-check',name:'报表差异检查',source:'repository',address:'repo://demo-orders-code/skills/report-check/SKILL.md',version:'initial',instructions:'先对齐时间、时区和订单状态；只读取证，交付差异与来源。',mcpIds:['demo-data-mcp'],readOnly:true,enabled:true,revision:1}]
  };
  const mcpFingerprint=x=>JSON.stringify([x.transport,x.address,x.credentialRef,x.tools,x.readOnly]);
  initial.mcps.forEach(x=>x.reviewFingerprint=mcpFingerprint(x));
  function blank(type,n){const id='demo-'+type+'-'+n;if(type==='projects')return {...window.CodeSource.defaults,authMode:'none',id,name:'新代码项目 '+n,address:'https://git.example.invalid/team/new-project.git',defaultRef:'refs/heads/test',paths:'src/',credentialRef:'',enabled:false,revision:1};if(type==='mcps')return {id,name:'新 MCP '+n,transport:'http',address:'https://tools.example.invalid/new/mcp',credentialRef:'',tools:'',readOnly:true,enabled:false,revision:1};return {id,name:'新 Skill '+n,source:'inline',address:'',version:'initial',instructions:'',mcpIds:[],readOnly:true,enabled:false,revision:1};}
  function editor(type,x,d){let body=`<h2>${{projects:'代码项目',mcps:'MCP 服务',skills:'Skill 方法'}[type]}</h2>${input('显示名称','name',x.name)}`;
    if(type==='projects')body+=window.CodeSource.editor(x)+`<label class="admin-field">项目说明 / 模块职责<textarea data-field="description" rows="3" maxlength="2000">${esc(x.description||'')}</textarea></label><p class="admin-muted">作为背景帮助理解代码；不作为资源授权或已核验事实。不填写凭据与敏感数据。</p>`;
    if(type==='mcps')body+=select('传输','transport',x.transport,[['http','Streamable HTTP'],['stdio','受控 stdio 启动模板']])+input(x.transport==='stdio'?'受信启动模板引用（template://…）':'MCP HTTPS 地址','address',x.address)+input('认证引用（可空）','credentialRef',x.credentialRef)+input('工具允许清单','tools',x.tools)+toggle('声明为只读工具（仍需实测）','readOnly',x.readOnly)+`<div class="admin-note">① 保存接入方式 → ② 模拟发现并审阅工具 → ③ 发布 → ④ 绑定系统环境。MCP 不直接绑定模型名称。</div><button type="button" data-admin="review-mcp">模拟发现并确认工具范围</button><p>${x.reviewFingerprint===mcpFingerprint(x)?'合成工具范围已确认':'工具范围待确认'} · 真实认证、schema 与资源限制未知</p><p>被 ${d.environments.filter(e=>(e.mcpIds||[]).includes(x.id)).length} 个环境引用；<a href="#admin-systems">前往系统环境绑定 →</a></p>`;
    if(type==='skills')body+=select('来源类型','source',x.source,[['inline','内联方法说明'],['repository','代码项目内文件'],['package','受控方法包']])+input('来源引用（repo:// / package://）','address',x.address)+input('方法版本','version',x.version)+`<label class="admin-field">方法说明<textarea data-field="instructions" rows="5">${esc(x.instructions)}</textarea></label>`+checks('所需 MCP（不是授权）','mcpIds',d.mcps,x.mcpIds)+toggle('仅用于只读检查','readOnly',x.readOnly);
    return body+toggle('启用这项目录配置','enabled',x.enabled)+`<div class="admin-note">目录修订 ${x.revision}。真实来源、内容摘要、能力和隔离均未验证。添加配置不会连接地址、拉代码、启动 MCP 或运行 Skill；Skill 描述不授予工具权限。</div>`;
  }
  function environment(env,d){return checks('此环境允许的 Agent / 模型','allowedModelIds',d.models.map(m=>({...m,name:m.agent+' / '+m.name})),env.allowedModelIds)+select('上下文策略','contextPolicyId',env.contextPolicyId||'demo-context-policy',d.contextPolicies.map(p=>[p.id,p.name]))+checks('此环境开放的检查流程','workflowIds',d.workflows,env.workflowIds)+select('此环境执行策略上限','policyMode',env.policyMode||'require_approval',[['allow_auto_readonly','允许受限自动只读（仍取用户权限交集）'],['require_approval','必须负责人审批'],['collect_only','仅收集问题']])+checks('代码项目','projectIds',d.projects,env.projectIds)+(env.projectIds||[]).map(id=>{const p=d.projects.find(x=>x.id===id);return p?.sourceKind==='local'?`<p class="admin-muted">${esc(p.name)} · 本地目录 / ${esc(p.executionHostRef)} · 运行时固定文件快照</p>`:p?`<label class="admin-field">${esc(p.name)} · 本环境分支 / commit 请求<input data-project-ref="${id}" value="${esc(env.projectRefs?.[id]||p.defaultRef)}"></label>`:'';}).join('')+checks('允许接入的 MCP','mcpIds',d.mcps,env.mcpIds)+checks('允许使用的 Skill','skillIds',d.skills,env.skillIds)+`<div class="resource-shortcuts"><button type="button" data-open-resource="projects">管理代码项目 ↗</button><button type="button" data-open-resource="mcps">管理 MCP ↗</button><button type="button" data-open-resource="skills">管理 Skill ↗</button></div><p class="admin-muted">环境绑定的是目录 ID 和已应用修订。运行前固定实际 commit、工具 schema 与 Skill 内容哈希；这些真实值目前未知。</p>`;}
  function validAddress(address,kind){if(kind==='template')return /^template:\/\/[A-Za-z0-9_./-]+$/.test(address);if(kind==='skill'&&address.split('/').includes('..'))return false;if(kind==='skill')return /^(repo|package):\/\/[A-Za-z0-9_./-]+$/.test(address);try{const u=new URL(address);return (kind!=='http'||u.protocol==='https:')&&['https:','ssh:'].includes(u.protocol)&&!!u.hostname&&!u.password&&!u.search&&!u.hash&&(u.protocol==='ssh:'||!u.username);}catch{return false;}}
  function issues(d){const out=[],add=(message,type,id,field)=>out.push({message,type,id,field});for(const [type,label] of [['projects','代码项目'],['mcps','MCP'],['skills','Skill']]){const names=new Set();for(const x of d[type]){
    if(!x.name.trim()||names.has(x.name.trim()))add(label+'名称不能为空或重复。',type,x.id,'name');names.add(x.name.trim());
    if(x.credentialRef&&!/^secret-ref\/[A-Za-z0-9_./-]+$/.test(x.credentialRef))add(x.name+' 只能填写 secret-ref/ 凭据引用。',type,x.id,'credentialRef');
    if(type==='projects')out.push(...window.CodeSource.issues(x));
    if(x.enabled){
      if(type==='projects'&&(x.sourceKind!=='local'&&(!validAddress(x.address,'git')||!x.defaultRef.trim())||(!x.paths.trim()||x.paths.split(',').some(p=>p.trim().startsWith('/')||/^[A-Za-z]:/.test(p.trim())||p.trim().includes('..')||p.includes('\\')))))add(x.name+' 的项目地址、版本或只读路径不合法。',type,x.id,x.sourceKind!=='local'&&!validAddress(x.address,'git')?'address':x.sourceKind!=='local'&&!x.defaultRef.trim()?'defaultRef':'paths');
      if(type==='mcps'&&(!x.tools.trim()||x.reviewFingerprint!==mcpFingerprint(x)))add(x.name+' 的合成工具范围需重新确认。','mcps',x.id,'tools');
      if(type==='mcps'&&!validAddress(x.address,x.transport==='stdio'?'template':'http'))add(x.name+' 的服务地址或受信启动模板不合法。',type,x.id,'address');
      if(type==='skills'&&(!x.version.trim()||!x.instructions.trim()||x.source!=='inline'&&!validAddress(x.address,'skill')))add(x.name+' 的方法版本、内容或来源不完整。',type,x.id,!x.version.trim()?'version':!x.instructions.trim()?'instructions':'address');
    }
    if(type==='skills'&&(x.mcpIds||[]).some(id=>!d.mcps.some(m=>m.id===id&&(!x.enabled||m.enabled))))add(x.name+' 所需 MCP 不存在或已停用。',type,x.id,'mcpIds');
  }}
  for(const env of d.environments){for(const [key,type] of [['projectIds','projects'],['mcpIds','mcps'],['skillIds','skills']])if((env[key]||[]).some(id=>!d[type].some(x=>x.id===id&&(!env.enabled||x.enabled))))add(env.name+' 关联资源不存在或已停用。','environments',env.id,key);for(const id of env.skillIds||[]){const skill=d.skills.find(x=>x.id===id);if(skill&&(skill.mcpIds||[]).some(mid=>!(env.mcpIds||[]).includes(mid)))add(env.name+' 缺少所选 Skill 要求的 MCP。','environments',env.id,'mcpIds');}}
  return out;}
  const errors=d=>issues(d).map(x=>x.message);
  function resolve(d,environmentId){const e=d.environments.find(x=>x.id===environmentId);return {configurationRevision:d.revision,environmentId,projects:(e?.projectIds||[]).map(id=>d.projects.find(x=>x.id===id)).filter(Boolean).map(p=>window.CodeSource.resolve(p,e.projectRefs?.[p.id])),mcps:(e?.mcpIds||[]).map(id=>d.mcps.find(x=>x.id===id)).filter(Boolean).map(x=>({...x,actualCapabilities:'unknown'})),skills:(e?.skillIds||[]).map(id=>d.skills.find(x=>x.id===id)).filter(Boolean).map(x=>({...x,verifiedContentHash:null})),realAdmission:'unknown'};}
  window.ResourceDesign={mcpFingerprint,initial,blank,editor,environment,errors,issues,resolve,modes,validEndpoint:value=>validAddress(value,'http')};
})();
